using ConjuntoInteligente.PbBridge.Contracts; using ConjuntoInteligente.PbBridge.Contracts.Dtos; using ConjuntoInteligente.PbBridge.Services; using Microsoft.AspNetCore.Mvc;
namespace ConjuntoInteligente.PbBridge.Controllers;
[Route("pb/v1/residents")] public sealed class PbResidentsController:PbBaseController{private readonly ICoreClient _core;private readonly IPbMapper _mapper;public PbResidentsController(ICoreClient core,IPbMapper mapper){_core=core;_mapper=mapper;}
 [HttpPost] public async Task<IActionResult> Create([FromBody]PbResidentCreateRequest request,CancellationToken ct){var result=await _core.PostAsync<CoreMaintenanceMutation>("api/v1/maintenance/residents",request,ct);return result is null?PbFail(PbErrorCodes.CoreError,"El core no devolvió el resultado de creación.",502):StatusCode(201,PbResponse<CoreMaintenanceMutation>.Success(result));}
 [HttpPut("{id}")] public async Task<IActionResult> Update(string id,[FromBody]PbResidentUpdateRequest request,CancellationToken ct){var result=await _core.PutAsync<CoreMaintenanceMutation>($"api/v1/maintenance/residents/{Uri.EscapeDataString(id)}",request,ct);return result is null?PbFail(PbErrorCodes.NotFound,"Residente no encontrado.",404):PbOk(result);}
 [HttpGet("list")] public async Task<IActionResult> List([FromQuery]string? torre,[FromQuery]string? busqueda,[FromQuery]int pagina=1,[FromQuery]int porPagina=100,CancellationToken ct=default){if(pagina<1||porPagina is <1 or >200)return PbFail(PbErrorCodes.ValidationError,"pagina debe ser positivo y porPagina debe estar entre 1 y 200.");var qs=new List<string>{$"page={pagina}",$"page_size={porPagina}"};if(!string.IsNullOrWhiteSpace(torre))qs.Add($"tower={Uri.EscapeDataString(torre!)}");if(!string.IsNullOrWhiteSpace(busqueda))qs.Add($"q={Uri.EscapeDataString(busqueda!)}");var page=await _core.GetAsync<CoreResidentPage>($"api/v1/maintenance/residents?{string.Join('&',qs)}",ct);return PbOk(new{items=(page?.Items??[]).Select(_mapper.ToPb).ToArray(),total=page?.Total??0,pagina,porPagina});}
 [HttpGet("{id}")] public async Task<IActionResult> Get(string id,CancellationToken ct){var r=await _core.GetAsync<CoreResident>($"api/v1/maintenance/residents/{Uri.EscapeDataString(id)}",ct);if(r is null)return PbFail(PbErrorCodes.NotFound,"Residente no encontrado.",404);return PbOk(_mapper.ToPb(r));}}
public sealed record CoreResidentPage(IReadOnlyList<CoreResident> Items,int Total);
